using System.Text;
using System.Text.Json;
using FVN_REGISTER.AI.Application.Abstractions;
using FVN_REGISTER.AI.Application.Contracts;
using FVN_REGISTER.AI.Infrastructure.Extraction;
using FVN_REGISTER.AI.Infrastructure.Persistence;
using FVN_REGISTER.AI.Infrastructure.Services;
using FVN_REGISTER.AI.Infrastructure.Validation;
using Microsoft.EntityFrameworkCore;
namespace FVN_REGISTER.AI.Tests;
public sealed class Phase1To3ExitGateTests
{
 [Fact] public async Task Representation_NormalizesPdfPagesAndTablesWithStableLocators(){var extractor=new DocumentRepresentationExtractor();var result=await extractor.ExtractAsync("[PAGE 2]\nEmployee name\n[ROW 1] E0001\tNguyen Van A\n[ROW 2] 2026-10-15\t08:00","application/pdf");Assert.Equal("1.0",result.Version);Assert.Equal(2,result.Pages.Single().PageNumber);Assert.Equal(2,result.Pages.Single().Rows.Count);Assert.Equal("page:2;row:1;cell:2",result.Pages.Single().Rows[0].Cells[1].Locator);Assert.Contains(result.Regions,x=>x.RegionType=="TableCell"&&x.Locator=="page:2;row:2;cell:1");}
 [Fact] public void Mapping_NormalizesOnlyDeclaredFields(){var schema=new ExtractionSchema("HR.EMPLOYEE",3,"Employee",[new("employeeCode","string"),new("email","email")],Mappings:[new("employeeCode",["Employee code","Mã nhân viên"],"Upper"),new("email",["Email"],"Lower")]);var code=JsonDocument.Parse("\" e0001 \"").RootElement.Clone();var email=JsonDocument.Parse("\"USER@EXAMPLE.COM\"").RootElement.Clone();var service=new ExtractionFieldMappingService();var result=service.Apply(schema,[new("employeeCode",code,.9,"page:1;line:1","e0001"),new("email",email,.9,"page:1;line:2","USER@EXAMPLE.COM")]);Assert.Equal("E0001",result[0].Value.GetString());Assert.Equal("user@example.com",result[1].Value.GetString());}
 [Fact] public async Task Validation_RejectsInvalidMappedValue(){var schema=new ExtractionSchema("HR.EMPLOYEE",1,"Employee",[new("employeeCode","string",Required:true,Pattern:"^[A-Z0-9]{5}$")]);var value=JsonDocument.Parse("\"bad\"").RootElement.Clone();var service=new ExtractionValidationService();var result=await service.ValidateAsync(new ExtractionValidationRequest(schema,[new("employeeCode",value,.95,"page:1;line:3","Employee code: bad")]));Assert.False(result.IsValid);Assert.Contains(result.Issues,x=>x.Code=="PATTERN_MISMATCH");Assert.Empty(result.AcceptedCandidates);}
 [Fact] public async Task Retention_ArchivesAndPurgesExpiredOriginalExactlyOnce(){var options=new DbContextOptionsBuilder<AiPlatformDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString("N")).Options;await using var db=new AiPlatformDbContext(options);var documentId=Guid.NewGuid();db.Documents.Add(new AiDocumentRecord{Id=documentId,TenantCode="T1",FileName="test.pdf",Extension=".pdf",MediaType="application/pdf",Length=10,Sha256=new string('a',64),StorageKey="tenant/T1/test.pdf",UploadedBy="tester",ReceivedAtUtc=DateTimeOffset.UtcNow.AddDays(-2),RetentionUntilUtc=DateTimeOffset.UtcNow.AddMinutes(-1),Status="AwaitingHumanReview"});await db.SaveChangesAsync();var store=new FakeDocumentStore();var service=new DocumentRetentionService(db,store);var first=await service.ArchiveExpiredAsync(DateTimeOffset.UtcNow);var second=await service.ArchiveExpiredAsync(DateTimeOffset.UtcNow.AddMinutes(1));var document=await db.Documents.SingleAsync();Assert.Equal(1,first.ArchivedDocuments);Assert.Equal(1,first.DeletedContent);Assert.Equal(0,second.ArchivedDocuments);Assert.Equal("Archived",document.Status);Assert.StartsWith("retained://purged/",document.StorageKey);Assert.Single(store.DeletedKeys);}
 private sealed class FakeDocumentStore:IOriginalDocumentStore{public List<string> DeletedKeys{get;}=[];public Task<StoredDocument> SaveAsync(Guid documentId,Stream content,CancellationToken cancellationToken=default)=>Task.FromResult(new StoredDocument($"test/{documentId:N}",content.Length,""));public Task<Stream> OpenReadAsync(string storageKey,CancellationToken cancellationToken=default)=>Task.FromResult<Stream>(new MemoryStream(Encoding.UTF8.GetBytes("test")));public Task DeleteAsync(string storageKey,CancellationToken cancellationToken=default){DeletedKeys.Add(storageKey);return Task.CompletedTask;}}
}
